import React, { useState } from 'react';
import { Box, TextField, Button, Typography, ButtonGroup } from '@mui/material';
import { reviewCode } from '../services/codeReviewService';

interface CodeEditorProps {
  taskDescription: string;
  onStatusChange: (status: 'completed' | 'failed' | 'abandoned') => void;
}

export const CodeEditor: React.FC<CodeEditorProps> = ({ taskDescription, onStatusChange }) => {
  const [code, setCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleCodeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setCode(event.target.value);
    setError(null);
  };

  const handleStatusChange = async (status: 'completed' | 'failed' | 'abandoned') => {
    try {
      setIsLoading(true);
      setError(null);

      if (status === 'completed' && !code.trim()) {
        setError('Пожалуйста, введите код перед отправкой');
        return;
      }

      if (status === 'completed') {
        const reviewData = await reviewCode(code, taskDescription);
        onStatusChange(status);
      } else {
        onStatusChange(status);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Произошла ошибка');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Box sx={{ mt: 2 }}>
      <TextField
        fullWidth
        multiline
        rows={10}
        value={code}
        onChange={handleCodeChange}
        placeholder="Введите ваш код здесь..."
        error={!!error}
        helperText={error}
        disabled={isLoading}
        sx={{
          '& .MuiInputBase-root': {
            fontFamily: 'monospace',
            fontSize: '14px',
            backgroundColor: 'grey.900',
            color: 'white',
            '& textarea': {
              color: 'white'
            }
          }
        }}
      />
      
      <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
        <ButtonGroup variant="contained" disabled={isLoading}>
          <Button
            color="success"
            onClick={() => handleStatusChange('completed')}
          >
            Решено
          </Button>
          <Button
            color="error"
            onClick={() => handleStatusChange('failed')}
          >
            Не решено
          </Button>
          <Button
            color="warning"
            onClick={() => handleStatusChange('abandoned')}
          >
            Пропустить
          </Button>
        </ButtonGroup>
      </Box>
    </Box>
  );
};
